+import ApplicationServices
+import Foundation
+
+func cfString(_ value: CFTypeRef?) -> String? {
+    guard let value else { return nil }
+    if CFGetTypeID(value) == CFStringGetTypeID() {
+        return value as? String
+    }
+    return nil
+}
+
+func attr(_ element: AXUIElement, _ name: CFString) -> CFTypeRef? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, name, &value)
+    return err == .success ? value : nil
+}
+
+func listChildren(_ element: AXUIElement, depth: Int, maxDepth: Int) {
+    let role = cfString(attr(element, kAXRoleAttribute)) ?? "?"
+    let title = cfString(attr(element, kAXTitleAttribute)) ?? cfString(attr(element, kAXDescriptionAttribute)) ?? ""
+    let subrole = cfString(attr(element, kAXSubroleAttribute)) ?? ""
+    let indent = String(repeating: "  ", count: depth)
+    print("\(indent)\(role)\(subrole.isEmpty ? "" : "/\(subrole)") \(title)")
+    guard depth < maxDepth else { return }
+    if let children = attr(element, kAXChildrenAttribute) as? [AXUIElement] {
+        for child in children {
+            listChildren(child, depth: depth + 1, maxDepth: maxDepth)
+        }
+    }
+}
+
+let systemWide = AXUIElementCreateSystemWide()
+var focusedAppRef: CFTypeRef?
+let err = AXUIElementCopyAttributeValue(systemWide, kAXFocusedApplicationAttribute, &focusedAppRef)
